window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"ASnplaINeO8","speaker":"Jakov Milatović","role":"President","country":"Montenegro","region":"Europe","url":"https://www.youtube.com/watch?v=ASnplaINeO8","date":"20260924","title":"🇲🇪 Montenegro -  President Addresses United Nations General Assembly 81st Session | #UNGA","seconds":1306,"words":2342,"counts":{"claims":35,"promises":2,"attacks":0},"topics":[{"topic":"EU enlargement","share":0.2272,"seconds":297},{"topic":"UN reform","share":0.1593,"seconds":208},{"topic":"Montenegro EU","share":0.1211,"seconds":158},{"topic":"Montenegro UN","share":0.1021,"seconds":133},{"topic":"Climate change","share":0.0521,"seconds":68},{"topic":"Iran","share":0.0504,"seconds":66},{"topic":"Future generations","share":0.0495,"seconds":65},{"topic":"Global conflicts","share":0.0482,"seconds":63},{"topic":"Montenegro education","share":0.048,"seconds":63},{"topic":"Montenegro diversity","share":0.0478,"seconds":62},{"topic":"Education","share":0.0474,"seconds":62},{"topic":"Israel-Gaza","share":0.0468,"seconds":61}],"timeline":[[1,73,null],[74,147,"Montenegro EU"],[149,212,"Global conflicts"],[214,286,"Montenegro UN"],[287,368,"EU enlargement"],[370,434,"EU enlargement"],[436,500,"EU enlargement"],[501,588,"EU enlargement"],[592,654,"Montenegro UN"],[655,729,"UN reform"],[731,799,"UN reform"],[800,861,"Israel-Gaza"],[863,928,"Iran"],[930,992,"Montenegro diversity"],[993,1058,"Future generations"],[1059,1122,"Montenegro education"],[1123,1185,"Education"],[1186,1255,"Climate change"],[1256,1341,"Montenegro EU"],[1343,1409,"UN reform"],[1410,1421,null]],"stances":{"Montenegro EU":"Jakov Milatović states that Montenegro is a credible NATO ally advancing towards EU membership and committed to regional cooperation.","Global conflicts":"Jakov Milatović states that the world has failed to keep its pledge, citing a record number of armed conflicts and human losses in 2025.","Montenegro UN":"Jakov Milatović states that Montenegro celebrates 20 years of UN membership as a sovereign nation and highlights the country's transformation from independence to shaping the Balkans.","EU enlargement":"Jakov Milatović states that Montenegro has made significant progress toward joining the European Union and views this goal as clearly achievable.","UN reform":"Jakov Milatović states that Montenegro strongly supports the UN reform agenda to make the organization more effective, agile, accessible, and financially sustainable.","Israel-Gaza":"Jakov Milatović states that Montenegro supports a two-state solution for Israel and Palestine, emphasizes the need to protect civilians and disarm Hamas, and asserts that human dignity must not have different standards.","Iran":"Jakov Milatović states that international law applies to freedom of navigation in the Strait of Hormuz and notes that disruptions there affect global energy markets, trade, and food security.","Montenegro diversity":"Jakov Milatović states that Montenegro's diverse character is a strength to be protected and that living together cannot be taken for granted.","Future generations":"Jakov Milatović argues that trust involves living with differences and that current decisions on peace, technology, and climate must not undermine the possibilities of future generations.","Montenegro education":"Jakov Milatović argues that young people should have real influence in decision-making and identifies education as a critical investment for their development.","Education":"Jakov Milatović argues that a child's potential is not limited by their country of origin and emphasizes the need to build educational and economic systems that retain talent, noting that artificial intelligence will increasingly influence these possibilities.","Climate change":"Jakov Milatović states that AI requires a human-centered approach to protect rights, while climate change demands long-term responsibility and global fairness, noting Montenegro's identity as an ecological state."},"claims":[{"t":82,"quote":"a credible NATO ally, steadily advancing towards membership in the European Union","topic":"Montenegro EU","kind":"fact"},{"t":157,"quote":"In 2025, the world witnessed more armed conflicts than in any year since 1946. 65 active conflicts, eight of which between the states.","topic":"Global conflicts","kind":"number"},{"t":174,"quote":"More than 240,000 lives lost to organized violence, the deadliest toll in three decades.","topic":"Global conflicts","kind":"number"},{"t":185,"quote":"about 120 million people driven from their homes, roughly one in 70.","topic":"Global conflicts","kind":"number"},{"t":235,"quote":"20 years ago, shortly after peacefully restoring our independence, Montenegro took its seat in this very assembly as a full member of the United And this year therefore holds a very special significance for us.","topic":"Montenegro UN","kind":"fact"},{"t":254,"quote":"We celebrate 20 years of our UN membership as a sovereign nation. A child born in Montenegro that year is now 20 years old.","topic":"Montenegro UN","kind":"number"},{"t":310,"quote":"In 2017, Montenegro joined NATO, strengthening not only our own security, but also contributing to the stability of our entire region.","topic":"EU enlargement","kind":"fact"},{"t":323,"quote":"We have kept good relations with our neighbors and demonstrated that the multiethnic, multi-religious and multicultural society can turn diversity into confidence, belonging, and the common purpose.","topic":"EU enlargement","kind":"fact"},{"t":382,"quote":"When the European perspective of the Balkans was reaffirmed at the Thessaloni summit in 2003, the world looked very and international cooperation were expanding back then.","topic":"EU enlargement","kind":"fact"},{"t":399,"quote":"The European Union was one of the most attractive political projects in the world and would welcome 13 new member states over the following decade.","topic":"EU enlargement","kind":"number"},{"t":436,"quote":"And this is why enlargement of the European Union is an act of strategic It is one of the best investments Europe can make in peace, security, and long-term stability.","topic":"EU enlargement","kind":"fact"},{"t":485,"quote":"Earlier this year, leaders from across Europe gathered in Montenegro for the European Union Western Balkan Summit.","topic":"EU enlargement","kind":"fact"},{"t":501,"quote":"It demonstrated how far our country has traveled and how close our European future has become.","topic":"EU enlargement","kind":"fact"},{"t":522,"quote":"Our region has carried the weight of division for too long and the new chapter is being written through cooperation, connectivity, economic opportunity and economic integration.","topic":"EU enlargement","kind":"fact"},{"t":598,"quote":"Montenegro is contributing to the vision that the Balkans become that proof.","topic":"Montenegro UN","kind":"fact"},{"t":621,"quote":"Montenegro is a reliable, credible, and predictable partner committed to an effective multilateral system with the UN charter at its core","topic":"Montenegro UN","kind":"self_credit"},{"t":655,"quote":"Eight decades after its foundation, the challenges confronting this organization are increasingly complex","topic":"UN reform","kind":"fact"},{"t":666,"quote":"Conflicts are eroding trust in in the international system. Climate change is testing the resilience of states and of societies","topic":"UN reform","kind":"fact"},{"t":731,"quote":"This responsibility also extends to the security council itself, which must become more effective, representative, accountable, and transparent.","topic":"UN reform","kind":"fact"},{"t":772,"quote":"Montenegro remains committed to supporting Ukraine and welcomes all credible diplomatic efforts aimed at the at bringing the war to this end.","topic":"UN reform","kind":"fact"},{"t":823,"quote":"Montenegro supports two-state solution with the state of Israel and indep and viable state of Palestine living side by side in peace, security and mutual recognition.","topic":"Israel-Gaza","kind":"fact"},{"t":839,"quote":"The disarmament of Hamas remains an important element of a sustainable settlement while full respect for international humanitarian law must guide us throughout.","topic":"Israel-Gaza","kind":"fact"},{"t":879,"quote":"Disruptions affect energy markets and global trade, but they also affect food security through the supply and price of fertilizers and other critical agricultural inputs with particularly serious consequences for vulnerable import dependent countries.","topic":"Iran","kind":"fact"},{"t":907,"quote":"In Sudan, in Myanmar, in Hayiti, and elsewhere, civilians continue to endure violence, displacement, and profound insecurity.","topic":"Iran","kind":"fact"},{"t":956,"quote":"Montenegro is proud of its multithnic, multi-religious and multicultural character.","topic":"Montenegro diversity","kind":"fact"},{"t":972,"quote":"Montenegro sits where the Mediterranean Sea meets the Balkans.","topic":"Montenegro diversity","kind":"fact"},{"t":1044,"quote":"The pact for the future reminds us of precisely this responsibility that the decisions we make today must not undermine the possibilities of those who will live with their consequences tomorrow.","topic":"Future generations","kind":"fact"},{"t":1103,"quote":"I was born and educated in Montenegro. And it was education, education which gave me the opportunity to study and work abroad, to learn from other countries, from other and to ultimately return home to serve my own country.","topic":"Montenegro education","kind":"self_credit"},{"t":1123,"quote":"It shaped my belief that the place where a child is born should never define the limits of what that child can become.","topic":"Education","kind":"fact"},{"t":1148,"quote":"Vision and wisdom are not measured by the size of a country but by the ideas we bring and the responsibility with which we act","topic":"Education","kind":"fact"},{"t":1181,"quote":"And artificial intelligence will increasingly shape those possibilities.","topic":"Education","kind":"fact"},{"t":1215,"quote":"Montenegro carries the identity and responsibility of an ecological state.","topic":"Climate change","kind":"fact"},{"t":1243,"quote":"those who have contributed the least to this crisis are too often the first and hardest hit by its","topic":"Climate change","kind":"fact"},{"t":1277,"quote":"We have built our institutions, secured our place on the global stage, strengthened our economy, strengthened our democracy, and brought our country within reach of membership in the European Union.","topic":"Montenegro EU","kind":"self_credit"},{"t":1354,"quote":"At the beginning of my address, I spoke about the meaning we attach to keeping one's word.","topic":"UN reform","kind":"fact"}],"promises":[{"t":764,"quote":"Montenegro will be a constructive partner in those efforts.","topic":"UN reform","kind":"promise"},{"t":1397,"quote":"Montenegro will continue to do its part at home, in our region, and here at this great organization of the United Nations.","topic":"UN reform","kind":"promise"}],"attacks":[],"greece":[],"said":[],"pickup":[],"transcript":[{"t":1,"topic":null,"text":"The assembly will hear an address by his excellency Yakov Milato, president of Montenegro. I request protocol to escort his excellency and invite him to address the Mr. President, I do want to congratulate first of all Dr. Rakman on his election as president of the United Nations General Assembly. And I also wish to thank Mrs. Burbuk for her leadership of the 80th session of the General Assembly. And let me also make a special thanks to Secretary General Gutieres whose stewardship of this organization and partnership with Montenegro over the past decade we deeply value."},{"t":74,"topic":"Montenegro EU","text":"It is my great honor to address you today as president of Montenegro, a Balkan and Mediterranean country, a credible NATO ally, steadily advancing towards membership in the European Union, and deeply committed to regional cooperation and effective multilateralism. In Montenegro, we have an old and simple saying, \"A person's word carries weight.\" This implies that a promise creates responsibility and what is true between people should also be true between nations. In the opening words of the UN charter, the nations of the world made perhaps the most important promise of all to save succeeding generations from the scourge of war. And eight decades later, as conflicts take lives and displace millions, geopolitical rivalries place the international system under growing pressure and new challenges test our collective capacity to respond."},{"t":149,"topic":"Global conflicts","text":"So how well have we kept our pledge? This is best told in numbers. In 2025, the world witnessed more armed conflicts than in any year since 1946. 65 active conflicts, eight of which between the states. More than 240,000 lives lost to organized violence, the deadliest toll in three decades. about 120 million people driven from their homes, roughly one in 70. So, are we leaving a better world to the generations after us? Or have we eroded trust in our collective capacity to evade conflicts and confront the challenges that face the world today? Trust is not built through declarations."},{"t":214,"topic":"Montenegro UN","text":"Trust is built when commitments are honored, when rules are applied consistently, and when institutions act with transposonsibility, and when people can see that international cooperation produces tangible results in their lives. 20 years ago, shortly after peacefully restoring our independence, Montenegro took its seat in this very assembly as a full member of the United And this year therefore holds a very special significance for us. We celebrate 20 years of our UN membership as a sovereign nation. A child born in Montenegro that year is now 20 years old. A generation has come of age, witnessing Montenegro's transformation from a newly independent state into a country, helping shape the Balkans, defined not by the conflicts of the past, but by the opportunities of the future."},{"t":287,"topic":"EU enlargement","text":"On the geostrategic front, Montenegro has paved the path towards our future in the European Union, which is now within our reach. Our goal is very clear by to see Montenegro's flag stand among the member states of the European Union. In 2017, Montenegro joined NATO, strengthening not only our own security, but also contributing to the stability of our entire region. We have kept good relations with our neighbors and demonstrated that the multiethnic, multi-religious and multicultural society can turn diversity into confidence, belonging, and the common purpose. At home, we have transformed our economy and strengthened the democratic institutions on which lasting prosperity Much work remains ahead of us, but the foundations have been laid for a society in which talent and effort open doors and the country where young people can imagine their future at home."},{"t":370,"topic":"EU enlargement","text":"For us, the European Union is not simply a destination we wish to reach, but a valuebased journey that we have embarked When the European perspective of the Balkans was reaffirmed at the Thessaloni summit in 2003, the world looked very and international cooperation were expanding back then. The European Union was one of the most attractive political projects in the world and would welcome 13 new member states over the following decade. At the same time, the Balkans was still emerging from the devastation and divisions of the '9s. More than two decades later, we live in a profoundly different international The international order is entering a new and uncertain phase."},{"t":436,"topic":"EU enlargement","text":"And this is why enlargement of the European Union is an act of strategic It is one of the best investments Europe can make in peace, security, and long-term stability. And Montenegro is proud to stand today at the forefront of that process, ready to serve as an example for the other Not because our journey has been without but because our journey demonstrates something essential, that progress is possible, that reforms matter, and that democratic political culture pays off. Earlier this year, leaders from across Europe gathered in Montenegro for the European Union Western Balkan Summit. For Montenegro, that gathering carried a meaning far beyond the protocol."},{"t":501,"topic":"EU enlargement","text":"It demonstrated how far our country has traveled and how close our European future has become. And it also sent an important message about our region that the future of the entire Balkan region lies within the European Union. Our region has carried the weight of division for too long and the new chapter is being written through cooperation, connectivity, economic opportunity and economic integration. and my generation has a responsibility to help complete that chapter. These responsibilities are not important because of the titles they carry. They're important because of what they allow us to contribute to connectivity, democratic resilience, and the European future of our region. and lasting reconciliation cannot be built on denial, selective approaches to justice, or the glorification of those convicted of war It requires respect for the judgments of international courts and equal dignity for every single victim, regardless of their identity or background."},{"t":592,"topic":"Montenegro UN","text":"And in a world searching for proof that cooperation still works, Montenegro is contributing to the vision that the Balkans become that proof. the principle that guides us at home, guide us here as well in this very organization. Our engagement with the United Nations system is guided by the same principles. Montenegro is a reliable, credible, and predictable partner committed to an effective multilateral system with the UN charter at its core, aligned with the European Union's common foreign security policy and working closely with our NATO allies and EU partners in support of international peace and security. And this commitment comes at a time when the United Nations itself is facing a profound test."},{"t":655,"topic":"UN reform","text":"Eight decades after its foundation, the challenges confronting this organization are increasingly complex and Conflicts are eroding trust in in the international system. Climate change is testing the resilience of states and of societies and artificial intelligence and other emerging technologies are creating risks at a speed that national frameworks alone cannot adequately address. So the answer cannot be less It must be more effective And Montenegro therefore strongly supports the UN reform agenda and the ambition to build the United Nations that is more effective, more agile, more accessible, more financially sustainable and fit for the challenges of our time. This reform must strengthen the UN's ability to deliver where it matters most in preventing conflict, protecting human rights and freedoms, advancing sustainable development, and responding effectively to humanitarian crisis."},{"t":731,"topic":"UN reform","text":"This responsibility also extends to the security council itself, which must become more effective, representative, accountable, and transparent. and the exercise of the veto must carry the weight of conscience above all when the world is confronted with mass atrocities and the largecale loss of civilian life. The charter of the United Nations must remain our common reference point and Montenegro will be a constructive partner in those efforts. Montenegro remains committed to supporting Ukraine and welcomes all credible diplomatic efforts aimed at the at bringing the war to this end. We believe that a just and lasting peace must be achieved through dialogue and In Gaza, our responsibility begins with the protection of human lives."},{"t":800,"topic":"Israel-Gaza","text":"Civilians must be protected and humanitarian assistance must reach those in need safely and without any obstruction. Israelis deserve lasting security and Palestinians deserve dignity, freedom, and a viable state of their own. Montenegro supports two-state solution with the state of Israel and indep and viable state of Palestine living side by side in peace, security and mutual recognition. The disarmament of Hamas remains an important element of a sustainable settlement while full respect for international humanitarian law must guide us throughout. Different conflicts have different But human dignity cannot have different standards."},{"t":863,"topic":"Iran","text":"Neither can international law. The same commitment to international law applies to freedom of navigation in the straight of Hormuz, a route whose security has implications far beyond the region. Disruptions affect energy markets and global trade, but they also affect food security through the supply and price of fertilizers and other critical agricultural inputs with particularly serious consequences for vulnerable import dependent countries. At the same time, we must not allow conflicts that receive less international attention to become forgotten conflicts. In Sudan, in Myanmar, in Hayiti, and elsewhere, civilians continue to endure violence, displacement, and profound insecurity. Dear colleagues, human rights are at the heart of the society we are building at home and of the international order we promote abroad."},{"t":930,"topic":"Montenegro diversity","text":"Human dignity is universal and That means protecting the rights and freedoms of every single person, combating discrimination and hate speech, and safeguarding the independent institutions, free media, civil society on which our democratic societies Montenegro is proud of its multithnic, multi-religious and multicultural character. We understand that diversity is not a challenge to be managed. It is a strength to be protected. Montenegro sits where the Mediterranean Sea meets the Balkans. We are a small country shaped by different cultures, religions, and identities. Our history has taught us that living together cannot be taken for granted."},{"t":993,"topic":"Future generations","text":"It has to be renewed by every generation. And perhaps this is why we understand so well that trust is not the absence of differences. Trust is the ability to live with those differences without allowing them to become And at a time of growing polarization, societies do not become stronger by making everyone the same. They become stronger by building institutions in which every single citizen can recognize the same fairness and the same dignity. the choices we make today, choices on peace, technology, and climate action will shape the lives of generations yet to come. The pact for the future reminds us of precisely this responsibility that the decisions we make today must not undermine the possibilities of those who will live with their consequences tomorrow."},{"t":1059,"topic":"Montenegro education","text":"But future generations should not only be the subject of our decisions. They should have a voice in making them. And Montenegro has heard the call from the young people to move from participation to real influence in decision making. Young people are not simply beneficiaries of public policy. They are partners in shaping it. and education. Education is our most powerful investment in young people, equipping them with knowledge, with critical thinking, with values they need to shape a better world. And this is very personal to me as well. I know what education can make possible. I was born and educated in Montenegro. And it was education, education which gave me the opportunity to study and work abroad, to learn from other countries, from other and to ultimately return home to serve my own country."},{"t":1123,"topic":"Education","text":"It shaped my belief that the place where a child is born should never define the limits of what that child can become. Coming from a small country, one can sometimes assume that greater size brings greater vision and greater wisdom. But the United Nations reminds us of a simple truth. Vision and wisdom are not measured by the size of a country but by the ideas we bring and the responsibility with which we act And our responsibility is to expand those possibilities to build schools that inspire, institutions that recognize talent, economies that reward ideas and work, and societies in which young people have a reason to stay. and those who left have a reason to return. And artificial intelligence will increasingly shape those possibilities."},{"t":1186,"topic":"Climate change","text":"But AI presents not only an extraordinary opportunity, it also creates a responsibility to ensure that technological transformation remains human- centered and rightsbased. Technology must remain at the service of humanity and not the other way around. Climate change demands the same long-term responsibility. Montenegro carries the identity and responsibility of an ecological state. Our mountains, our rivers, our forests, and the Adriatic Sea are not simply natural resources. They are part of our national identity and of the legacy we will leave to our future generations. But climate change is also a question of global fairness because those who have contributed the least to this crisis are too often the first and hardest hit by its And no country can solve this challenge alone."},{"t":1256,"topic":"Montenegro EU","text":"This is one of the clearest reasons why effective multilateralism remains indispensable. to conclude, 20 years ago, Montenegro entered this very hole at the beginning of a new chapter in our history. We have built our institutions, secured our place on the global stage, strengthened our economy, strengthened our democracy, and brought our country within reach of membership in the European Union. Our transformation is not complete, but its direction is very clear. And when the next generation of Montenegro stands in this hall 20 years from now, I hope they will be able to say that we used our moment well, that Montenegro completed successfully its European journey, that our region, the Balkans, left all divisions behind, and that we stood firmly in defense of the rules and principles that protect peace in the But above all, I hope they will be able to say something much simpler that we gave them more opportunities than we had ourselves."},{"t":1343,"topic":"UN reform","text":"Because that is ultimately the responsibility of leadership, not simply to manage the present, but to expand the possibilities of the future. At the beginning of my address, I spoke about the meaning we attach to keeping one's word. And perhaps this is also what the United Nations needs most today. Not new promises for every new challenge, but a renewed confidence that the promises we have already made still carry weight. to uphold the UN charter, to protect human dignity, to preserve peace, and to leave those who come after us with more possibilities than we inherited ourselves. Montenegro will continue to do its part at home, in our region, and here at this great organization of the United Nations."},{"t":1410,"topic":null,"text":"I thank you very much. On behalf of the assembly, I wish to thank the president of Montenegro"}],"compare":[{"topic":"Europe","share":0.2272,"mean":0.003,"rank":1,"others":8},{"topic":"UN & its reform","share":0.1593,"mean":0.205,"rank":114,"others":170},{"topic":"Climate Change","share":0.0521,"mean":0.0427,"rank":64,"others":77},{"topic":"Iran","share":0.0504,"mean":0.0136,"rank":26,"others":25},{"topic":"Sustainable Development","share":0.0495,"mean":0.0123,"rank":23,"others":28},{"topic":"International Law & Order","share":0.0482,"mean":0.0605,"rank":93,"others":102},{"topic":"Education","share":0.0474,"mean":0.002,"rank":5,"others":6},{"topic":"Israel–Palestine","share":0.0468,"mean":0.0524,"rank":73,"others":76}]};
